1	import java.util.List;
2	
3	/**
4	 * A class representing shared characteristics of animals.
5	 *
6	 * @version 2022/03/02
7	 */
8	public abstract class Animal extends Creature
9	{
10	    // sex of an animal, 0 = female and 1 = male
11	    private int sex;
12	
13	    // The amount of oxygen an animal needs to survive.
14	    protected static final double ANIMAL_OXYGEN_REQUIRED = 0.0000009;
15	
16	    private boolean infected;
17	    private boolean immune;
18	    private int infectionStartStep;
19	
20	    private static int diseaseDeathCount = 0;
21	
22	    // Age and food level shared by all animal subclasses.
23	    protected int age;
24	    protected int foodLevel;
25	
26	    public Animal(Field field, Location location) {
27	        super(field, location);
28	        sex = Randomizer.getRandom().nextInt(2);
29	        infected = false;
30	        immune = false;
31	        infectionStartStep = 0;
32	    }
33	
34	    // -----------------------------------------------------------------------
35	    // Abstract methods — subclasses supply species-specific values and types.
36	    // -----------------------------------------------------------------------
37	
38	    protected abstract int getBreedingAge();
39	    protected abstract int getMaxAge();
40	    protected abstract double getBreedingProbability();
41	    protected abstract int getMaxLitterSize();
42	
43	    /** Factory method: return a newborn of this species placed at location. */
44	    protected abstract Animal createYoung(Field field, Location location);
45	
46	    /**
47	     * Look for food adjacent to the current location.
48	     * Herbivores eat seaweed; carnivores hunt prey animals.
49	     * Also spreads disease from infected neighbours encountered during the search.
50	     */
51	    public abstract Location search(Disease disease, int step);
52	
53	    // -----------------------------------------------------------------------
54	    // Template act() — identical lifecycle for every animal species.
55	    // -----------------------------------------------------------------------
56	
57	    /**
58	     * Core lifecycle: check oxygen, handle disease, age, hunger, breed, move.
59	     *
60	     * @return oxygen consumed (negative) or 0 if the animal died this step.
61	     */
62	    public double act(List<Creature> newAnimals, boolean atDayTime, double oxygenLevel, Disease disease, int step) {
63	        if(oxygenLevel < ANIMAL_OXYGEN_REQUIRED) {
64	            setDead();
65	            return 0;
66	        }
67	        if(dieOfInfection(disease)) return 0;
68	        ifCanGrantImmunity(disease, step);
69	        incrementAge();
70	        incrementHunger();
71	        if(isAlive() && isAwake(atDayTime)) {
72	            giveBirth(newAnimals);
73	            Location newLocation = search(disease, step);
74	            if(newLocation == null) {
75	                newLocation = getField().freeAdjacentLocation(getLocation());
76	            }
77	            if(newLocation != null) {
78	                setLocation(newLocation);
79	            } else {
80	                setDead();
81	            }
82	        }
83	        return -ANIMAL_OXYGEN_REQUIRED;
84	    }
85	
86	    // -----------------------------------------------------------------------
87	    // Shared breeding and lifecycle helpers.
88	    // -----------------------------------------------------------------------
89	
90	    /** Increase age; die on reaching MAX_AGE. */
91	    protected void incrementAge() {
92	        age++;
93	        if(age > getMaxAge()) {
94	            setDead();
95	        }
96	    }
97	
98	    /** Decrease food level; die on starvation. */
99	    protected void incrementHunger() {
100	        foodLevel--;
101	        if(foodLevel <= 0) {
102	            setDead();
103	        }
104	    }
105	
106	    /** True if old enough and a mate of the same species and opposite sex is nearby. */
107	    private boolean canBreed() {
108	        return age >= getBreedingAge() && hasMateNearby();
109	    }
110	
111	    /** Return the number of offspring produced this step (may be zero). */
112	    private int breed() {
113	        int births = 0;
114	        if(canBreed() && Randomizer.getRandom().nextDouble() <= getBreedingProbability()) {
115	            births = Randomizer.getRandom().nextInt(getMaxLitterSize()) + 1;
116	        }
117	        return births;
118	    }
119	
120	    /** Place offspring of this species in adjacent free locations. */
121	    private void giveBirth(List<Creature> newAnimals) {
122	        Field field = getField();
123	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
124	        int births = breed();
125	        for(int b = 0; b < births && free.size() > 0; b++) {
126	            Location loc = free.remove(0);
127	            newAnimals.add(createYoung(field, loc));
128	        }
129	    }
130	
131	    /**
132	     * True if an animal of the same species but opposite sex is within radius 2.
133	     * Uses getClass() so each species only matches its own kind.
134	     */
135	    private boolean hasMateNearby() {
136	        List<Location> adjacent = getField().adjacentLocations(getLocation(), 2);
137	        for(Location loc : adjacent) {
138	            Object obj = getField().getObjectAt(loc);
139	            if(obj != null && obj.getClass() == this.getClass()) {
140	                Animal other = (Animal) obj;
141	                if(this.getSex() != other.getSex()) return true;
142	            }
143	        }
144	        return false;
145	    }
146	
147	    // -----------------------------------------------------------------------
148	    // Disease mechanics.
149	    // -----------------------------------------------------------------------
150	
151	    /**
152	     * Force this animal into the infected state, recording when the infection began.
153	     * Used by Disease during an outbreak; bypasses the immunity probability check.
154	     */
155	    protected void infect(int step) {
156	        setInfected(true);
157	        if(infectionStartStep == 0) {
158	            infectionStartStep = step;
159	        }
160	    }
161	
162	    /**
163	     * Probabilistically infect this animal via contact with a diseased neighbour.
164	     * Has no effect if the animal is already immune.
165	     */
166	    protected void makeInfected(Disease disease, int step) {
167	        if(!isImmune() && Randomizer.getRandom().nextDouble() <= disease.INFECTION_RATE)
168	            setInfected(true);
169	        if(isInfected() && infectionStartStep == 0)
170	            infectionStartStep = step;
171	    }
172	
173	    /**
174	     * Grant immunity once the animal has withstood the disease long enough.
175	     */
176	    protected void ifCanGrantImmunity(Disease disease, int step) {
177	        if(isInfected() && !isImmune()) {
178	            if(step - infectionStartStep >= disease.STEPS_TO_IMMUNITY) {
179	                setImmune(true);
180	                setInfected(false);
181	            }
182	        }
183	    }
184	
185	    /**
186	     * Kill the animal if it succumbs to infection this step.
187	     * @return true if the animal died of infection.
188	     */
189	    protected boolean dieOfInfection(Disease disease) {
190	        if(isInfected() && !isImmune()) {
191	            if(Randomizer.getRandom().nextDouble() <= disease.MORTALITY_RATE) {
192	                setDead();
193	                diseaseDeathCount++;
194	                return true;
195	            }
196	        }
197	        return false;
198	    }
199	
200	    /** Return the total number of animals that have died of disease in this run. */
201	    public static int getDiseaseDeathCount() { return diseaseDeathCount; }
202	
203	    /** Reset the disease-death counter (call when the simulation resets). */
